package local.thor.bilichannels;
import org.json.*;import java.util.*;
public final class Comment {
 public final long id,authorId,time;public long rootId,parentId;public Map<String,Emote> emotes=Collections.emptyMap();public final String name,avatar,message,location;public final int replies;public long likes;public boolean liked,busy;public final List<Comment> children;
 Comment(long id,long authorId,long time,String name,String avatar,String message,String location,int replies,long likes,boolean liked,List<Comment> children){this.id=id;this.authorId=authorId;this.time=time;this.name=name;this.avatar=avatar;this.message=message;this.location=location;this.replies=replies;this.likes=likes;this.liked=liked;this.children=children;}
 public static Comment parse(JSONObject j){JSONObject member=j.optJSONObject("member"),content=j.optJSONObject("content"),control=j.optJSONObject("reply_control");List<Comment> children=new ArrayList<>();JSONArray sub=j.optJSONArray("replies");if(sub!=null)for(int i=0;i<Math.min(2,sub.length());i++)if(sub.optJSONObject(i)!=null)children.add(parseChild(sub.optJSONObject(i)));Comment parsed=new Comment(j.optLong("rpid_str",j.optLong("rpid")),member==null?j.optLong("mid"):member.optLong("mid"),j.optLong("ctime"),member==null?"用户":member.optString("uname","用户"),member==null?"":ApiModels.secure(member.optString("avatar")),content==null?"":content.optString("message"),control==null?"":control.optString("location"),j.optInt("rcount",j.optInt("count")),Math.max(0,j.optLong("like")),j.optInt("action")==1,children);parsed.rootId=j.optLong("root_str",j.optLong("root"));parsed.parentId=j.optLong("parent_str",j.optLong("parent"));parsed.emotes=Emote.parse(content==null?null:content.optJSONObject("emote"));return parsed;}
 public static final class Emote {
  public final String token,url;public final int size;
  Emote(String token,String url,int size){this.token=token;this.url=url;this.size=size;}
  static Map<String,Emote> parse(JSONObject data){Map<String,Emote> out=new LinkedHashMap<>();if(data!=null)for(Iterator<String> keys=data.keys();keys.hasNext()&&out.size()<128;){String key=keys.next();JSONObject value=data.optJSONObject(key);if(value==null||key.isEmpty()||key.length()>100)continue;String url=ApiModels.secure(value.optString("url"));if(!url.startsWith("https://"))continue;JSONObject meta=value.optJSONObject("meta");out.put(key,new Emote(key,url,meta!=null&&meta.optInt("size")==2?2:1));}return Collections.unmodifiableMap(out);}
 }
 static Comment parseChild(JSONObject j){JSONObject copy=new JSONObject();try{for(Iterator<String> keys=j.keys();keys.hasNext();){String key=keys.next();if(!key.equals("replies"))copy.put(key,j.opt(key));}}catch(Exception ignored){}return parse(copy);}
 public static final class Page {public final List<Comment> rows;public final int page;public final long total;public final boolean more;Page(List<Comment> rows,int page,long total,boolean more){this.rows=rows;this.page=page;this.total=total;this.more=more;}}
 public static Page page(JSONObject data,int requested){JSONObject p=data.optJSONObject("page");int num=p==null?requested:p.optInt("num",requested),size=p==null?20:p.optInt("size",20);long count=p==null?-1:p.optLong("count",-1);JSONArray raw=data.optJSONArray("replies");List<Comment> rows=new ArrayList<>();Set<Long> seen=new HashSet<>();JSONObject upper=data.optJSONObject("upper");if(num==1&&upper!=null&&upper.optJSONObject("top")!=null)add(rows,seen,upper.optJSONObject("top"));if(raw!=null)for(int i=0;i<raw.length();i++)if(raw.optJSONObject(i)!=null)add(rows,seen,raw.optJSONObject(i));boolean more=raw!=null&&raw.length()>0&&(count>=0?(long)num*Math.max(1,size)<count:raw.length()>=size);return new Page(rows,num,count,more);}
 static void add(List<Comment> rows,Set<Long> seen,JSONObject j){Comment c=parse(j);if(c.id>0&&seen.add(c.id))rows.add(c);}
 public static List<Comment> demo(){List<Comment> out=new ArrayList<>();for(int i=0;i<24;i++)out.add(new Comment(i+1,i+1,0,new String[]{"掌机研究员","周末放映室","双屏玩家"}[i%3],"",new String[]{"上屏看视频，下屏翻评论，这才是双屏的快乐。","这个滚动舒服多了！手指拖着走，松手还有柔和的惯性。","头像、正文、时间和点赞终于各归各位啦。\n横竖屏切换也能接着看。"}[i%3],"离线演示",0,i*7,false,new ArrayList<>()));return out;}
}
